referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  return {
    text: d.text.slice(d.start, d.end),
    ranges: d.ranges
      .map((r) => [Math.max(r[0], d.start) - d.start, Math.min(r[1], d.end) - d.start, r[2]])
      .filter((r) => r[0] < r[1]),
  };
}

referenceSolutions.typescript:
type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  return {
    text: d.text.slice(d.start, d.end),
    ranges: d.ranges
      .map((r: any[]) => [Math.max(r[0], d.start) - d.start, Math.min(r[1], d.end) - d.start, r[2]])
      .filter((r: any[]) => r[0] < r[1]),
  };
}
